export const runCoreInformationModelExample = () => {
  const { core } = createExampleCoreComposition()
  core.defineSystemProperty(STATUS_KEY, {
    revision: 0,
    status: 'draft'
  })

  try {
    core.setSystemProperty(STATUS_KEY, {
      revision: 1,
      status: 'verified'
    })
    const model = core.getSystemContextSnapshot()[STATUS_KEY]
    const result = {
      model,
      optionalSystems: {
        ai: 'not-composed',
        collaboration: 'not-composed',
        renderEngine: core.hasRenderEngineProvider()
      }
    }

    assertExampleResult(model.status === 'verified', 'status is verified')
    assertExampleResult(model.revision === 1, 'revision is one')
    assertExampleResult(
      result.optionalSystems.renderEngine === false,
      'Render remains optional'
    )
    return Object.freeze(result)
  } finally {
    core.unregisterSystemProperty(STATUS_KEY)
  }
}

export const runPreset2DMinimalExample = () => {
  const { core } = createExampleCoreComposition()
  const result = applyPreset(core)

  assertExampleResult(result.profile === PresetProfiles['2D'], 'profile is 2D')
  assertExampleResult(
    result.presetEngineId === '@asyra/render-engine-pixi',
    'the official Pixi provider is selected'
  )
  assertExampleResult(
    result.appliedDefaults.length === Object.values(PresetDefaults).length,
    'all official defaults are applied'
  )
  return result
}

export const runPresetSelectiveDefaultsExample = () => {
  const { core } = createExampleCoreComposition()
  const result = applyPreset(core, {
    defaults: [PresetDefaults.VECTOR_EDITING]
  })
  const expected = [
    PresetDefaults.VECTOR,
    PresetDefaults.SELECTION,
    PresetDefaults.VECTOR_EDITING
  ]

  assertExampleResult(
    JSON.stringify(result.selectedDefaults) ===
      JSON.stringify([PresetDefaults.VECTOR_EDITING]),
    'only Vector Editing is selected'
  )
  assertExampleResult(
    JSON.stringify(result.appliedDefaults) === JSON.stringify(expected),
    'dependency expansion is exact and ordered'
  )
  return result
}

export const runCustomComponentSchemaExample = () => {
  const { core } = createExampleCoreComposition()
  const ReviewState = core.definePropertyComponent({
    type: PROPERTY_TYPE,
    defaults: { score: 0, status: 'draft' }
  })
  core.registerPropertySchema({
    type: PROPERTY_TYPE,
    fields: [
      { key: 'status', kind: 'string', defaultValue: 'draft' },
      { key: 'score', kind: 'number', defaultValue: 0 }
    ]
  })
  core.defineComponent({
    type: COMPONENT_TYPE,
    properties: [{ name: 'review', type: PROPERTY_TYPE }]
  })

  try {
    const review = new ReviewState({
      id: 'review-1',
      type: PROPERTY_TYPE,
      score: 92,
      status: 'approved'
    })
    const result = {
      componentType: COMPONENT_TYPE,
      relations: core.getComponentPropertyRelations(COMPONENT_TYPE),
      schema: core.getPropertySchema(PROPERTY_TYPE),
      value: {
        score: review.get('score'),
        status: review.get('status')
      }
    }

    assertExampleResult(result.relations.length === 1, 'one relation exists')
    assertExampleResult(result.value.score === 92, 'score is retained')
    assertExampleResult(
      result.value.status === 'approved',
      'status is retained'
    )
    return Object.freeze(result)
  } finally {
    core.unregisterComponent(COMPONENT_TYPE)
    core.unregisterPropertyRegistration(PROPERTY_TYPE)
  }
}

export const runFeatureSessionUndoExample = async () => {
  const state = { value: 0 }
  factory.registerTransactionInverter(EVENT, (event) => ({
    type: event.type,
    payload: {
      before: event.payload.after,
      after: event.payload.before
    }
  }))
  const stopReplay = factory.registerTransactionReplayHandler(
    EVENT,
    (event) => {
      state.value = event.payload.after
      return true
    }
  )
  const sessions = new SessionManager()
  sessions.registerSession(SESSION, FEATURE, 100, true, 'rollback', {
    onStart: () => ({ startedAt: state.value }),
    onUpdate: (snapshot) => {
      recordValue(state, snapshot.nextValue)
      if (snapshot.fail === true) {
        throw new Error('app mutation rejected')
      }
    },
    onEnd: () => undefined,
    onCancel: () => 'rollback'
  })

  try {
    await sessions.handleStart(SESSION, {})
    await sessions.handleUpdate(SESSION, { nextValue: 5 })
    await sessions.handleEnd(SESSION, {})
    const committedDepth = factory.getUndoHistoryDepth()
    factory.undo()
    const undone = state.value
    factory.redo()
    const redone = state.value

    await sessions.handleStart(SESSION, {})
    let rollbackError
    try {
      await sessions.handleUpdate(SESSION, { fail: true, nextValue: 9 })
    } catch (error) {
      rollbackError = error
    }
    const result = {
      committedDepth,
      rollbackDepth: factory.getUndoHistoryDepth(),
      rollbackError: rollbackError?.message,
      rolledBackValue: state.value,
      undone,
      redone
    }

    assertExampleResult(committedDepth === 1, 'session creates one Undo unit')
    assertExampleResult(undone === 0, 'Undo restores the starting value')
    assertExampleResult(redone === 5, 'Redo restores the committed value')
    assertExampleResult(
      result.rolledBackValue === 5,
      'failed update rolls back completely'
    )
    assertExampleResult(
      result.rollbackDepth === 1,
      'rollback adds no history entry'
    )
    return Object.freeze(result)
  } finally {
    sessions.unregisterSession(SESSION, FEATURE)
    stopReplay()
  }
}

export const registerAppVersionMigrations = (core, options) => {
  const registry = createConnectedMigrationRegistry(options?.migrations)
  if (registry.size === 0) {
    return
  }
  if (migrationInstallations.has(core)) {
    throw new AppMigrationError(
      APP_MIGRATION_ERROR_CODES.ALREADY_REGISTERED,
      'This app migration helper already installed a dispatcher on the Core instance',
      undefined
    )
  }

  core.registerLoadHook((rawDocument) => {
    let document = requireVersionedDocument(rawDocument)
    const visited = new Set()

    while (registry.has(document.version)) {
      if (visited.has(document.version)) {
        throw new AppMigrationError(
          APP_MIGRATION_ERROR_CODES.INVALID_CHAIN,
          `Migration dispatch encountered a cycle at ${document.version}`,
          document.version
        )
      }
      visited.add(document.version)

      const step = /** @type {AppMigrationStep} */ (
        registry.get(document.version)
      )
      const migrated = /** @type {unknown} */ (step.migrate(document))
      if (
        isRecord(migrated) &&
        'then' in migrated &&
        typeof migrated.then === 'function'
      ) {
        void Promise.resolve(migrated).catch(() => undefined)
        throw new AppMigrationError(
          APP_MIGRATION_ERROR_CODES.ASYNC_UNSUPPORTED,
          `Migration from ${step.from} returned an unsupported asynchronous result`,
          step.from
        )
      }
      if (!isRecord(migrated) || typeof migrated.version !== 'string') {
        throw new AppMigrationError(
          APP_MIGRATION_ERROR_CODES.INVALID_STEP_RESULT,
          `Migration from ${step.from} must return a document with version ${step.to}`,
          undefined
        )
      }

      const migratedVersion = migrated.version
      if (migratedVersion !== step.to) {
        throw new AppMigrationError(
          APP_MIGRATION_ERROR_CODES.INVALID_STEP_RESULT,
          `Migration from ${step.from} must produce version ${step.to}`,
          migratedVersion
        )
      }

      document = /** @type {AppDocument} */ (migrated)
    }

    return document
  })
  migrationInstallations.add(core)
}

/**
 * Copyable example only: replace these app schema fields with the product's
 * actual domain transforms.
 *
 * @param {LoadHookRegistrar} core
 */
export const installExampleAppMigrations = (core) => {
  registerAppVersionMigrations(core, {
    migrations: [
      {
        from: 'v1',
        to: 'v2',
        migrate: (document) => {
          const { legacyTitle, ...rest } = document
          return {
            ...rest,
            version: 'v2',
            title: typeof legacyTitle === 'string' ? legacyTitle : ''
          }
        }
      },
      {
        from: 'v2',
        to: 'v3',
        migrate: (document) => ({
          ...document,
          version: 'v3',
          metadata: {
            ...(isRecord(document.metadata) ? document.metadata : {}),
            schema: 'v3'
          }
        })
      }
    ]
  })
}

export const runCustomRenderBoundaryExample = async () => {
  const concreteEngine = new RecordingRenderEngine({
    name: 'example-concrete-engine'
  })
  const appOwnedAdapter = {
    name: 'example-app-adapter',
    capabilities: concreteEngine.capabilities,
    initialize: (options) => concreteEngine.initialize(options),
    execute: (command) => concreteEngine.execute(command),
    query: (query) => concreteEngine.query(query),
    subscribeToInteraction: (listener) =>
      concreteEngine.subscribeToInteraction(listener),
    requestFrame: (callback) => concreteEngine.requestFrame(callback),
    cancelFrame: () => concreteEngine.cancelFrame(),
    destroy: () => concreteEngine.destroy()
  }
  const report = await runRenderEngineContract({
    createEngine: () => appOwnedAdapter,
    emitInteraction: (_engine, event) => concreteEngine.emitInteraction(event),
    getOperationTypes: () =>
      concreteEngine.getOperations().map(({ type }) => type)
  })

  assertExampleResult(
    report.engine === appOwnedAdapter,
    'the app adapter remains the runtime boundary'
  )
  assertExampleResult(
    report.operationTypes.at(-1) === 'destroy',
    'the complete lifecycle reaches destroy'
  )
  return Object.freeze({
    engineName: report.engine.name,
    interactionCount: report.interactions.length,
    operationTypes: report.operationTypes
  })
}

// The hub represents an app/server-owned live room and acknowledgement
// boundary. Production apps can replace it with any Provider.
export const createMemoryHub = (options = {}) => new MemoryHub(options)

// Awareness is app-owned presentation state. It never authorizes or applies a
// canonical mutation and it is absent from document publications.
export const projectRemotePresence = (awareness, present) =>
  awareness.observe((event) => {
    if (event.type === 'updated') {
      present.set(event.snapshot.actorId, event.snapshot.state)
      return
    }
    present.delete(event.actorId)
  })

export const createCollaboratingCounter = async ({
  hub,
  documentId,
  roomId,
  actorId
}) => {
  const factory = new Factory()
  factory.registerSharedDataChannel(CHANNEL, new LocalSharedDataChannel())
  const state = { value: 0 }

  factory.registerTransactionInverter(SET_VALUE, (event) => ({
    type: event.type,
    payload: {
      ...event.payload,
      before: event.payload.after,
      after: event.payload.before
    }
  }))
  factory.registerTransactionReplayHandler(SET_VALUE, (event) => {
    state.value = event.payload.after
    return true
  })

  const recordAndApply = (payload) => {
    factory.updateTransaction({
      type: 'updateTransaction',
      eventName: SET_VALUE,
      payload,
      options: {
        undoable: true,
        rollbackable: true,
        shared: CHANNEL,
        sharedDelivery: 'transaction-end'
      }
    })
    state.value = payload.after
  }

  const provider = new MemoryProvider(hub, {
    documentId,
    roomId,
    actorId
  })
  const collaboration = createCollaboration({
    documentId,
    roomId,
    actorId,
    publicationSource: {
      subscribe: (subscriber) =>
        factory.subscribeToSharedPublication(subscriber)
    },
    provider,
    processRemotePublication: (publication) => {
      const deliveryEntries = publication.slices.flatMap((slice) =>
        slice.batches.flatMap((batch) =>
          batch.deliveries.map((delivery) => ({
            channel: batch.channel,
            delivery
          }))
        )
      )
      if (
        deliveryEntries.length === 0 ||
        deliveryEntries.some(
          ({ channel, delivery }) =>
            channel !== CHANNEL ||
            delivery.eventName !== SET_VALUE ||
            !isSetValuePayload(delivery.payload)
        )
      ) {
        throw new Error('Unsupported counter publication')
      }
      factory.runRemoteTransaction(() => {
        deliveryEntries.forEach(({ delivery }) =>
          recordAndApply(delivery.payload)
        )
      })
    },
    resourceOwnership: { provider: 'owned' }
  })
  const remotePresence = new Map()
  const stopPresenceProjection = projectRemotePresence(
    collaboration.awareness,
    remotePresence
  )

  // Construction is inert. start() is the explicit live-connection point.
  await collaboration.start()

  return Object.freeze({
    collaboration,
    factory,
    remotePresence,
    getValue: () => state.value,
    setValue: (after) => {
      factory.startTransaction()
      recordAndApply({ before: state.value, after })
      factory.endTransaction()
    },
    undo: () => factory.undo(),
    redo: () => factory.redo(),
    updatePresence: (presence) => collaboration.updateAwareness(presence),
    disconnect: () => collaboration.disconnect(),
    reconnect: () => collaboration.reconnect(),
    dispose: async () => {
      stopPresenceProjection()
      await collaboration.dispose()
    }
  })
}

export const createExampleAiRuntime = () => {
  const state = {
    visible: true
  }
  const transactionEvidence = {
    commits: 0,
    rollbacks: 0
  }
  const providerInputs = []
  const serverArguments = {
    visible: false
  }

  const runtime = createAiAgentRuntime({
    provider: {
      requestActionBatch: async (input) => {
        providerInputs.push(input)
        return {
          batchId: 'example-batch',
          explanation: 'Apply one registered action.',
          actions: [
            {
              arguments: serverArguments,
              id: 'visibility-1',
              name: SET_VISIBILITY,
              summary: {
                affectedCount: 1,
                kind: 'visibility'
              }
            }
          ]
        }
      }
    },
    actionDefinitions: [
      {
        name: SET_VISIBILITY,
        description: 'Set example visibility.',
        inputSchema: {
          type: 'object',
          additionalProperties: false,
          required: ['visible'],
          properties: {
            visible: {
              type: 'boolean'
            }
          }
        },
        execute: async (args) => {
          if (args !== serverArguments) {
            throw new Error('Runtime replaced the server-prepared arguments.')
          }
          const { visible } = args
          state.visible = visible
          return {
            visible
          }
        }
      }
    ],
    contextProvider: {
      getContext: async () => ({
        currentVisibility: state.visible
      })
    },
    permissionPolicy: {
      evaluate: async ({ action }) => {
        if (action.arguments !== serverArguments) {
          throw new Error('Permission received different action arguments.')
        }
        return 'allow'
      }
    },
    confirmationHandler: {
      confirm: async () => false
    },
    transactionRunner: {
      run: async (_label, execute) => {
        try {
          const result = await execute()
          transactionEvidence.commits += 1
          return result
        } catch (error) {
          transactionEvidence.rollbacks += 1
          throw error
        }
      }
    }
  })

  return Object.freeze({
    dispose: () => runtime.dispose(),
    getEvidence: () => ({
      providerInputs: [...providerInputs],
      transaction: {
        ...transactionEvidence
      },
      visible: state.visible
    }),
    run: (intent = 'hide the example') =>
      runtime.run({
        intent,
        signal: new AbortController().signal
      })
  })
}

export const runAppRetrievalActionExample = () => {
  const { core } = createExampleCoreComposition()
  core.defineSystemProperty(RECORDS_KEY, {
    'record-a': { label: 'Cooling audit', status: 'open' },
    'record-b': { label: 'Safety review', status: 'open' }
  })
  const registration = core.defineFeature(FEATURE, undefined, {
    priority: 100,
    exclusive: true,
    api: {
      setStatus: (recordId, status) => {
        const records = core.getSystemContextSnapshot()[RECORDS_KEY]
        core.setSystemProperty(RECORDS_KEY, {
          ...records,
          [recordId]: { ...records[recordId], status }
        })
      }
    }
  })

  try {
    const retrieve = (query) => {
      const records = core.getSystemContextSnapshot()[RECORDS_KEY]
      return Object.entries(records)
        .filter(([, record]) =>
          record.label.toLowerCase().includes(query.toLowerCase())
        )
        .map(([id, record]) => ({ id, ...record }))
    }
    const before = core.getSystemContextSnapshot()[RECORDS_KEY]
    const matches = retrieve('safety')
    const afterSearch = core.getSystemContextSnapshot()[RECORDS_KEY]
    registration.api.setStatus(matches[0].id, 'approved')
    const afterAction = core.getSystemContextSnapshot()[RECORDS_KEY]
    const result = { afterAction, afterSearch, before, matches }

    assertExampleResult(matches.length === 1, 'retrieval is deterministic')
    assertExampleResult(
      JSON.stringify(before) === JSON.stringify(afterSearch),
      'retrieval does not mutate canonical state'
    )
    assertExampleResult(
      afterAction['record-b'].status === 'approved',
      'the Feature API applies the accepted action'
    )
    return Object.freeze(result)
  } finally {
    registration.dispose()
    core.unregisterSystemProperty(RECORDS_KEY)
  }
}

export const installReviewQueueExtension = () => {
  const records = new Map()

  const api = {
    add(input) {
      if (
        !input ||
        typeof input.id !== 'string' ||
        !input.id.trim() ||
        typeof input.title !== 'string' ||
        !input.title.trim()
      ) {
        throw new Error('Review records require non-empty id and title')
      }
      if (records.has(input.id)) {
        throw new Error(`Review record already exists: ${input.id}`)
      }

      const record = snapshotRecord({
        id: input.id,
        status: 'pending',
        title: input.title
      })
      records.set(record.id, record)
      return record
    },
    list() {
      return [...records.values()]
    }
  }

  const feature = defineFeature(FEATURE_NAME, undefined, {
    api,
    priority: 20,
    exclusive: true
  })

  return Object.freeze({
    api: feature.api,
    dispose: feature.dispose,
    featureName: FEATURE_NAME
  })
}
